#include <catch2/catch_test_macros.hpp>

#include "slic3r/GUI/JusPrin/Shell/OrcaUpdateFilter.hpp"
#include "slic3r/Utils/PresetUpdater.hpp"

using Slic3r::GUI::JusPrin::OrcaUpdateFilter;

TEST_CASE("OrcaSlicer's update result never reaches its handlers", "[OrcaUpdateFilter]")
{
    OrcaUpdateFilter filter;
    wxCommandEvent found(EVT_SLIC3R_VERSION_ONLINE);
    found.SetString("2.5.0-alpha");
    CHECK(filter.FilterEvent(found) == wxEventFilter::Event_Processed);
}

TEST_CASE("Every other event passes through", "[OrcaUpdateFilter]")
{
    OrcaUpdateFilter filter;
    wxCommandEvent click(wxEVT_BUTTON);
    CHECK(filter.FilterEvent(click) == wxEventFilter::Event_Skip);
}
